"""Requested SPX15 1.5R / NAS15 2R composition, isolated offline replay."""
import argparse,json,shutil
from pathlib import Path
from .data import Market,write,sha,stamp,reconstruct
from .engine import Account
from .control_check import inputs
from .run import describe,correlations,entry_identity,END
from .baseline import detailed
from .audit import reconcile
from research_monitor.atlas_opportunity_study import COSTS
from research_monitor.atlas_portfolio_controller import APPROVED


def main():
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);root=p.parse_args().root.resolve();out=root/'outputs/atlas_two_strategy_exits_v1';out.mkdir(exist_ok=False);previous=root/'outputs/atlas_two_strategy_5000_v1';exit_root=root/'outputs/atlas_exit_management_v1';original_protocol=json.loads((exit_root/'comparison/protocol.json').read_text());assert sha(Path(__file__).parent/'engine.py')==original_protocol['sources']['engine.py'];frozen={str(f.relative_to(root)):sha(f) for f in [previous/'results.json',previous/'private_fills_01.json',previous/'private_fills_02.json',exit_root/'comparison/results.json',exit_root/'comparison/portfolio.json',root/'work/tradingbot/local-results/atlas-forward-v2/freeze.json']}
    write(out/'protocol.json',dict(registered_utc=stamp(),request='SPX50015m fixed1.5R plus NAS10015m fixed2R; exclude NAS5. Shared5000USD account. Preserve original entryconditions,naturalstops,holdingdeadlines,risklimits.',dates=['2025-12-15','2026-10-30'],styles={'SPX15':'original','NAS15':'fixed_2'},approved_risk=APPROVED,costs=COSTS,method='Fresh shared chronological replay,not subtraction of NAS5 losses. Compare archived two-lane1.5R/1.5R standard/higher; new severe1.5R/1.5R comparator because no archived severe exists. Independently reconstruct all new full quote drawdowns and archived controls.',independent_validation=False,all_historical_prices_reused=True,paper_account_unchanged=True,preserved_sha256=frozen,source_sha256={f.name:sha(f) for f in Path(__file__).parent.glob('*.py')},limitations=['Commission6/12/18USD roundtrip per full CFD lot proxies,not verified account fees','Historical clock and contract/margin applicability unverified','Observed bid/ask;scaled spreads and deterministic tickslippage;severe1secondexitdelay and2xmargin;liquidity unverified','Stops/entrypauses do not guarantee realizedloss or drawdown bound','No newprospective outcome or independentOOS claim']))
    (out/'source').mkdir()
    for f in Path(__file__).parent.glob('*.py'):shutil.copy2(f,out/'source'/f.name)
    write(out/'progress.json',dict(status='running',phase='load_original_inputs',completed=0,total=4));all_lanes,meta=inputs(root);lanes={n:l for n,l in all_lanes.items() if n in ['SPX15','NAS15']};entry_hash=entry_identity(lanes);write(out/'entry_identity.json',entry_hash);market=Market(root,exit_root);baseline=[];results=[];audits={};old=json.loads((previous/'results.json').read_text())
    for i,r in enumerate(old,1):
        fills=json.loads((previous/f'private_fills_{i:02}.json').read_text());curve,_=reconstruct(market,fills,meta,COSTS[r['cost']],5000.);assert abs(curve['quote_drawdown_pct']-r['quote_drawdown_pct'])<1e-7;assert abs(sum(f['pnl'] for f in fills)-r['net_pnl'])<1e-6;assert len(fills)==r['trades'];baseline.append(dict(cost=r['cost'],initial_equity=5000.,ending_balance=r['ending_balance'],net_pnl=r['net_pnl'],trades=r['trades'],win_rate=r['win_rate'],quote_drawdown_pct=r['quote_drawdown_pct'],metrics={k:v for k,v in r['metrics'].items() if not k.startswith('daily_')},source='Preserved original two-strategy1.5R/1.5R ledger',audit_pass=True,curve=curve['curve']))
    jobs=[('baseline','severe',{'SPX15':'original','NAS15':'original'})]+[('requested',c,{'SPX15':'original','NAS15':'fixed_2'}) for c in COSTS]
    for i,(kind,cost,styles) in enumerate(jobs):
        write(out/'progress.json',dict(status='running',phase=kind,cost=cost,completed=i,total=4));book=Account(market,lanes,meta,COSTS[cost],styles);book.run_to(END);account=book.result();assert account['open_positions']==0 and account['incomplete_paths']==0;metrics=describe(book);audit=reconcile(market,book.fills,meta,COSTS[cost],account);key=kind+'_'+cost;audits[key]=audit;write(out/f'private_fills_{key}.json',book.fills);write(out/f'private_decisions_{key}.json',book.decisions)
        for decision in book.decisions:
            if decision['status']=='EXECUTED':assert decision['planned_risk']<=decision['lane_budget']+1e-7 and decision['planned_risk']+decision['used_risk']<=decision['total_budget']+1e-7
        row=dict(cost=cost,styles=styles,initial_equity=5000.,ending_balance=account['ending_balance'],net_pnl=account['net_pnl'],trades=account['trades'],win_rate=account['win_rate'],quote_drawdown_pct=account['quote_drawdown_pct'],account=account,metrics=metrics,strategies={n:dict(detailed([f for f in book.fills if f['strategy']==n],5000.),quote_contribution_drawdown_pct=audit['contribution_quote_drawdown'][n]) for n in lanes},correlations=correlations(book.fills),audit_pass=True,independent_validation=False)
        if kind=='baseline':row['source']='New severe-cost1.5R/1.5R comparator; no original benchmark overwritten';row['curve']=audit['curve'];baseline.append(row)
        else:results.append(row)
        write(out/'results.json',results);write(out/'baseline.json',baseline);write(out/'independent_audit.json',dict(all_pass=True,records=audits));print(json.dumps(dict(kind=kind,cost=cost,net=row['net_pnl'],trades=row['trades'],win_rate=row['win_rate'],quote_drawdown_pct=row['quote_drawdown_pct'])),flush=True)
    assert entry_identity(lanes)==entry_hash and all(sha(root/k)==v for k,v in frozen.items());comparison=[]
    for r in results:
        b=next(x for x in baseline if x['cost']==r['cost']);comparison.append(dict(cost=r['cost'],baseline_net=b['net_pnl'],new_net=r['net_pnl'],net_delta=r['net_pnl']-b['net_pnl'],baseline_drawdown=b['quote_drawdown_pct'],new_drawdown=r['quote_drawdown_pct'],drawdown_delta_percentage_points=r['quote_drawdown_pct']-b['quote_drawdown_pct'],new_ending_balance=r['ending_balance'],new_trades=r['trades'],new_win_rate=r['win_rate'],new_annualized_extrapolation=r['metrics']['annualized_extrapolation_pct']))
    write(out/'comparison.json',comparison);write(out/'completed.json',dict(completed_utc=stamp(),new_replays=4,all_arithmetic_and_quote_drawdown_pass=True,original_benchmarks_preserved=True,paper_account_unchanged=True,independently_validated=False));report(out,results,baseline,comparison);write(out/'progress.json',dict(status='completed',completed=4,total=4));print(json.dumps(comparison))


def report(out,results,baseline,comparison):
    import csv,html
    with (out/'comparison.csv').open('w',newline='',encoding='utf-8') as f:
        writer=csv.DictWriter(f,fieldnames=list(comparison[0]));writer.writeheader();writer.writerows(comparison)
    num=lambda x:f'{x:,.2f}'
    money=lambda x:('−$' if x<0 else '+$')+num(abs(x))
    cells=lambda values:'<tr>'+''.join('<td>'+str(v)+'</td>' for v in values)+'</tr>'
    rows=''.join(cells([c['cost'].title(),money(c['baseline_net']),money(c['new_net']),money(c['net_delta']),num(c['baseline_drawdown'])+'%',num(c['new_drawdown'])+'%','$'+num(c['new_ending_balance']),c['new_trades'],num(c['new_win_rate'])+'%',num(c['new_annualized_extrapolation'])+'%']) for c in comparison)
    contributions=''.join(cells([r['cost'].title(),n,m['trades'],num(m['win_rate'])+'%',money(m['net_pnl']),money(m['average_win']),money(m['average_loss']),num(m['profit_factor']),money(m['expectancy_dollars']),num(m['average_winning_planned_R']),num(m['quote_contribution_drawdown_pct'])+'%']) for r in results for n,m in r['strategies'].items())
    content='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trade Dashboard</title><style>body{margin:0;background:#0b1320;color:#e5edf8;font:14px/1.65 "Segoe UI",sans-serif}main{max-width:1400px;margin:auto;padding:40px}h1{font-size:36px}h2{font-size:23px}p{color:#aab9ce}section{padding:25px;background:#142133;border:1px solid #293b53;border-radius:15px;margin:22px 0}.badge{color:#59deb0;letter-spacing:.1em;font-size:12px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:13px}td,th{text-align:right;border-bottom:1px solid #293b53;padding:13px}td:first-child,th:first-child{text-align:left}th{color:#aab9ce}a{color:#80b7ff}.notice{border-left:3px solid #f4cf82;padding:15px;background:#f4cf8209}.cards{display:flex;gap:20px;flex-wrap:wrap}.cards div{flex:1;min-width:200px}.cards strong{font-size:22px}</style><main><span class="badge">PROJECT ATLAS · PAPER ONLY</span><h1>Trade Dashboard</h1><p>SPX500 15m at 1.5R + NAS100 15m at 2R · Nasdaq 5m excluded</p><div class="notice">Historical replay using previously exposed prices. No independent validation or experimental deployment. Original entries, natural initial stops, holding deadlines and approved risk controller remain unchanged.</div><section><div class="cards"><div><strong>$5,000</strong><p>Initial shared simulated balance</p></div><div><strong>15 Dec 2025 – 30 Oct 2026</strong><p>320 calendar days; annualized figures are extrapolations</p></div><div><strong>Four new replays</strong><p>Three requested cost scenarios plus a severe-cost original-exit comparator</p></div></div></section><section><h2>Original two-strategy exits versus requested exits</h2><p>Original comparison: both strategies at 1.5R. Standard/higher rows are preserved archived results; the severe original-exit comparator is newly calculated because no archived severe two-strategy run existed.</p><div class="scroll"><table><thead><tr><th>Costs</th><th>Original net</th><th>Requested net</th><th>Δ net</th><th>Original DD</th><th>Requested DD</th><th>Ending balance</th><th>Trades</th><th>Win rate</th><th>Annualized*</th></tr></thead><tbody>ROWS</tbody></table></div></section><section><h2>Contributions within the requested shared account</h2><p>Contributions reflect actual shared-account allocations, not standalone accounts. Contribution drawdown marks one strategy against $5,000; portfolio drawdown above includes both strategies together.</p><div class="scroll"><table><thead><tr><th>Costs</th><th>Strategy</th><th>Trades</th><th>Win rate</th><th>Net</th><th>Average win</th><th>Average loss</th><th>PF</th><th>Expectancy</th><th>Winning net R</th><th>Contribution DD</th></tr></thead><tbody>CONTRIBUTIONS</tbody></table></div></section><section><h2>Risk and verification</h2><p>All-in planned risk per trade: min(0.5% current equity,$25). Gross combined open risk:1% equity ($50 initially). Daily-loss entry pause:2%. Peak-equity drawdown entry pause:10%. No arbitrary daily trade-count quota. Multiple legal same-direction positions permitted within gross risk and margin. Conflicts and duplicates blocked. Stops and entry pauses do not guarantee realized loss limits.</p><p>All new ledgers independently reconcile net P&amp;L and full observed bid/ask quote drawdown. All positions closed and no incomplete paths. Archived original standard/higher ledger totals and quote drawdown independently checked. Original reports and actual paper-forward account unchanged.</p><p>Standard: archived spread, $6 roundtrip/full CFD lot,1 adverse tick per side. Higher:1.5× spread,$12,2 ticks. Severe:2× spread,$18,4 ticks,1-second observed exit delay and2× margin proxy. Actual account fees,historical clock,contract/margin applicability and executable liquidity remain unverified. These are NAS100/SPX500 CFDs,not MNQ/MES futures.</p><p><a href="comparison.csv">Download comparison CSV</a> · <a href="results.json">Detailed metrics</a> · <a href="protocol.json">Registered protocol</a></p></section></main></html>'''
    (out/'report.html').write_text(content.replace('ROWS',rows).replace('CONTRIBUTIONS',contributions),encoding='utf-8')


if __name__=='__main__':main()
